   /**
    * @brief Computes a hash value for a given GNSS key.
    *
    * The hash is computed by combining the hash of the GNSS constellation type and
    * the satellite ID. A bit shift operation is used to avoid collisions.
    *
    * @param key The GNSS key to hash.
    * @return A hash value for the given GNSS key.
    */
   std::size_t operator()(const GnssKey& key) const
   {
      const std::size_t hash1 = std::hash<int>{}(static_cast<int>(key.constellation));
      const std::size_t hash2 = std::hash<int>{}(key.satelliteId.value);

      static constexpr std::size_t SATELLITE_SHIFT = 1;

      return hash1 ^ (hash2 << SATELLITE_SHIFT);
   }

