   const std::filesystem::path hlfFile{optArgs.at(0)};

   if (!hlfFile.has_extension() || (hlfFile.extension().string() != HLF_EXTENSION))
   {
      throw InvalidArgumentsException(
         "Unrecognized input file extension: " + hlfFile.extension().string());
   }

   if (!std::filesystem::exists(hlfFile))
   {
      throw InvalidArgumentsException("Input file does not exist: " + hlfFile.string());
   }

   s_split.inputFile = hlfFile;

   s_convert.enabled = false;
   s_version.enabled = false;
   s_help.enabled = false;
   s_commandFlag = SPLIT_FLAG;
}

