/// @brief Resize the matrix to new dimensions.
   ///
   /// Changes the logical size of the matrix without reallocating the buffer.
   /// The new size must not exceed the maximum capacity specified in the template parameters.
   ///
   /// @param rows New number of rows.
   /// @param newCols New number of columns.
   ///
   void resize(int newRows, int newCols)
   {
      if (newRows <= 0 || newCols <= 0)
      {
         throw InvalidArgumentException("Rows and columns must be positive");
      }

      if ((newRows == this->rows()) && (newCols == this->cols()))
      {
         return;
      }

      if (newRows > static_cast<int>(MAX_ROWS) || newCols > static_cast<int>(MAX_COLS))
      {
         throw InvalidArgumentException(
            "Source map dimensions exceed maximum allowed by template parameters");
      }

      new (static_cast<Map*>(this)) Map(m_buffer, newRows, newCols);
   }

