   const double longitude = std::atan2(cartesian.y, cartesian.x);
   double height = 0.0;
   double horizontalDistance = std::sqrt((cartesian.x * cartesian.x) + (cartesian.y * cartesian.y));
   if (horizontalDistance < XY_POSITION_EPSILON) // Close to a pole
   {
      const double temp
         = bmc::half_pi<double>() - (horizontalDistance / SEMI_MINOR_AXIS); // avoid redundant code
      if (cartesian.z > 0.0)                                                // North pole
      {
         latitude = temp;
      }
      else if (cartesian.z < 0.0) // South pole
      {
         latitude = -1.0 * temp;
      }
      else // Center of coordinate system
      {
         throw InvalidArgumentException(
            "Cannot convert coordinates at origin (0,0,0) to geodetic coordinates.");
      }
      height = fabs(cartesian.z) - SEMI_MINOR_AXIS;
      return GeodeticCoordinates{latitude, longitude, height};
