bool TcpClientReceivingService::handleDataReception()
{
   std::vector<uint8_t> buffer;
   buffer.resize(TCP_BUFFER_SIZE);

   if (!m_tcpClient->receiveData(buffer))
   {
      std::string const tcpError = m_tcpClient->getLastErrorDescription();

      print(
         PrintLevel::Info,
         "Connection error to " + m_tcpClient->getSocketAddress() + " (reason: " + tcpError
            + ") - attempting to reconnect");

      m_tcpClient->disconnect();
      m_state = ServiceState::Reconnecting;
      m_connectionMessagePrinted = false;
      m_dataReceivedMessagePrinted = false;
      return false;
   }

   // Connection was closed
   if (!m_tcpClient->isConnected() && buffer.empty())
   {
      m_keepRunning.store(false);
   }

   if (buffer.empty())
   {
      return false;
   }

   if (m_noDataReceivedReported)
   {
      m_noDataReceivedReported = false;
   }

   m_timeDataLastReceived = std::chrono::steady_clock::now();

   if (!m_dataReceivedMessagePrinted)
   {
      print(PrintLevel::Info, "Data is being received on stream " + std::to_string(m_streamId));

      m_dataReceivedMessagePrinted = true;
   }

   m_callback(m_streamId, buffer);
   return true;
}

