// checks that vector contains a one of each variants of engine (checks size and uniqueness)
bool isUniqueFullVariantSet(const std::vector<Alpha::Replay::EngineFactory::EngineVariant>& vec)
{
   // clang-tidy false positive on constexpr with variant_size_v
   // NOLINTNEXTLINE(cppcoreguidelines-init-variables)
   constexpr std::size_t numTypes
      = std::variant_size_v<Alpha::Replay::EngineFactory::EngineVariant>;

   if (vec.size() != numTypes)
   {
      return false; // Must be exactly one of each type
   }

   std::unordered_set<std::type_index> seen;

   for (const auto& variant : vec)
   {
      std::type_index type = std::visit(
         [](auto&& value) {
            return std::type_index(typeid(value));
         },
         variant);

      if (!seen.insert(type).second)
      {
         return false; // Duplicate type found
      }
   }

   return seen.size() == numTypes;
}
